PRAGMA foreign_keys=ON;
PRAGMA user_version=1;
CREATE TABLE metadata (singleton INTEGER PRIMARY KEY CHECK(singleton=1), schema_version INTEGER NOT NULL CHECK(schema_version=1), profile_digest TEXT NOT NULL, boot_id TEXT NOT NULL, resource_id TEXT NOT NULL UNIQUE, clock_high_water INTEGER NOT NULL CHECK(clock_high_water>=0));
CREATE TABLE intents (intent_id TEXT PRIMARY KEY, workflow_execution_id TEXT NOT NULL, failure_occurrence_id TEXT NOT NULL, workflow_id TEXT NOT NULL, failed_step_id TEXT NOT NULL, journal_digest TEXT NOT NULL, plan_digest TEXT NOT NULL, frozen_intent_json TEXT NOT NULL, binding_digest TEXT NOT NULL, UNIQUE(workflow_execution_id,failure_occurrence_id));
CREATE TABLE dispatches (dispatch_id TEXT PRIMARY KEY, intent_id TEXT NOT NULL UNIQUE REFERENCES intents(intent_id), state TEXT NOT NULL CHECK(state IN ('ready','leased','executing','retry-scheduled','terminal')), version INTEGER NOT NULL CHECK(version>=0), max_fence INTEGER NOT NULL CHECK(max_fence>=0));
CREATE TABLE occurrences (dispatch_id TEXT NOT NULL REFERENCES dispatches(dispatch_id), occurrence_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 7), operation_id TEXT NOT NULL, invocation_id TEXT NOT NULL UNIQUE, binding_digest TEXT NOT NULL, payload_digest TEXT NOT NULL, payload_json TEXT NOT NULL, continuation TEXT NOT NULL CHECK(continuation IN ('retry','escalate','terminal-failure')), policy_ref TEXT NOT NULL, PRIMARY KEY(dispatch_id,occurrence_id), UNIQUE(dispatch_id,ordinal));
CREATE TABLE claims (claim_id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL REFERENCES dispatches(dispatch_id), claimant_id TEXT NOT NULL, fence INTEGER NOT NULL CHECK(fence>0), acquired_version INTEGER NOT NULL CHECK(acquired_version>=0), acquired_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('current','released','superseded')), UNIQUE(dispatch_id,fence), UNIQUE(dispatch_id,claim_id));
CREATE UNIQUE INDEX one_current_claim ON claims(dispatch_id) WHERE state='current';
CREATE TABLE leases (lease_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES claims(claim_id), generation INTEGER NOT NULL CHECK(generation>0), valid_from INTEGER NOT NULL, expires_at INTEGER NOT NULL CHECK(expires_at>valid_from), renewed_from TEXT REFERENCES leases(lease_id), UNIQUE(claim_id,generation), UNIQUE(claim_id,lease_id));
CREATE TABLE attempts (attempt_id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL, occurrence_id TEXT NOT NULL, attempt_number INTEGER NOT NULL CHECK(attempt_number BETWEEN 1 AND 3), claim_id TEXT NOT NULL, lease_id TEXT NOT NULL, fence INTEGER NOT NULL CHECK(fence>0), started_at INTEGER NOT NULL, finished_at INTEGER, outcome TEXT CHECK(outcome IN ('succeeded','failed','unknown')), evidence_json TEXT, UNIQUE(dispatch_id,occurrence_id,attempt_number), UNIQUE(dispatch_id,occurrence_id,attempt_id), FOREIGN KEY(dispatch_id,occurrence_id) REFERENCES occurrences(dispatch_id,occurrence_id), FOREIGN KEY(dispatch_id,claim_id) REFERENCES claims(dispatch_id,claim_id), FOREIGN KEY(claim_id,lease_id) REFERENCES leases(claim_id,lease_id), CHECK((finished_at IS NULL AND outcome IS NULL) OR (finished_at IS NOT NULL AND outcome IS NOT NULL AND evidence_json IS NOT NULL)));
CREATE TABLE progress (dispatch_id TEXT NOT NULL, occurrence_id TEXT NOT NULL, result_digest TEXT NOT NULL, result_evidence_json TEXT NOT NULL, recorded_at INTEGER NOT NULL, PRIMARY KEY(dispatch_id,occurrence_id), FOREIGN KEY(dispatch_id,occurrence_id) REFERENCES occurrences(dispatch_id,occurrence_id));
CREATE TABLE retries (dispatch_id TEXT NOT NULL, occurrence_id TEXT NOT NULL, predecessor_attempt_id TEXT NOT NULL, successor_number INTEGER NOT NULL CHECK(successor_number BETWEEN 2 AND 3), not_before INTEGER NOT NULL, remaining_budget INTEGER NOT NULL CHECK(remaining_budget BETWEEN 1 AND 2), policy_ref TEXT NOT NULL, PRIMARY KEY(dispatch_id,occurrence_id,successor_number), FOREIGN KEY(dispatch_id,occurrence_id,predecessor_attempt_id) REFERENCES attempts(dispatch_id,occurrence_id,attempt_id));
CREATE TABLE terminals (dispatch_id TEXT PRIMARY KEY REFERENCES dispatches(dispatch_id), disposition TEXT NOT NULL CHECK(disposition IN ('completed','exhausted','escalated')), semantic_status TEXT NOT NULL CHECK(semantic_status IN ('satisfied','unresolved')), final_attempt_id TEXT REFERENCES attempts(attempt_id), cause TEXT NOT NULL, evidence_json TEXT NOT NULL, recorded_at INTEGER NOT NULL, CHECK((disposition='completed' AND semantic_status='satisfied') OR (disposition IN ('exhausted','escalated') AND semantic_status='unresolved')));
CREATE TABLE transitions (transition_id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL REFERENCES dispatches(dispatch_id), version INTEGER NOT NULL CHECK(version>=0), command_digest TEXT NOT NULL, evidence_json TEXT NOT NULL, UNIQUE(dispatch_id,version));
CREATE TABLE dispatch_outbox (event_id TEXT PRIMARY KEY, transition_id TEXT NOT NULL UNIQUE REFERENCES transitions(transition_id), payload_json TEXT NOT NULL, delivered_at INTEGER);
CREATE TRIGGER immutable_intent_update BEFORE UPDATE ON intents BEGIN SELECT RAISE(ABORT,'immutable-intent'); END;
CREATE TRIGGER immutable_intent_delete BEFORE DELETE ON intents BEGIN SELECT RAISE(ABORT,'immutable-intent'); END;
CREATE TRIGGER immutable_occurrence_update BEFORE UPDATE ON occurrences BEGIN SELECT RAISE(ABORT,'immutable-plan'); END;
CREATE TRIGGER immutable_occurrence_delete BEFORE DELETE ON occurrences BEGIN SELECT RAISE(ABORT,'immutable-plan'); END;
CREATE TRIGGER monotonic_progress_update BEFORE UPDATE ON progress BEGIN SELECT RAISE(ABORT,'immutable-progress'); END;
CREATE TRIGGER monotonic_progress_delete BEFORE DELETE ON progress BEGIN SELECT RAISE(ABORT,'immutable-progress'); END;
